CREATE TABLE training_sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),course_id UUID NOT NULL REFERENCES training_courses(id),session_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,location VARCHAR(255),instructor VARCHAR(255),notes TEXT,status VARCHAR(30) NOT NULL,CHECK(end_time>start_time));
CREATE TABLE training_participants(session_id UUID NOT NULL REFERENCES training_sessions(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES employees(id),PRIMARY KEY(session_id,employee_id));
CREATE TABLE attendance(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),session_id UUID NOT NULL REFERENCES training_sessions(id),employee_id UUID NOT NULL REFERENCES employees(id),status VARCHAR(20) NOT NULL CHECK(status IN('PRESENT','ABSENT','LATE','EXCUSED')),recorded_by VARCHAR(255),recorded_at TIMESTAMPTZ NOT NULL,remark TEXT,UNIQUE(session_id,employee_id));